import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CDU0sSpB.js";const h=JSON.parse('{"title":"Memory and Capability Evolution","description":"How Hearth accumulates correctable context and reusable methods without creating unsourced, unforgettable, or self-expanding memory.","frontmatter":{"title":"Memory and Capability Evolution","description":"How Hearth accumulates correctable context and reusable methods without creating unsourced, unforgettable, or self-expanding memory.","outline":false},"headers":[],"relativePath":"en/design/memory.md","filePath":"en/design/memory.md","lastUpdated":1793863446000}'),s={name:"en/design/memory.md"};function i(n,e,d,c,l,m){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="memory-and-capability-evolution" tabindex="-1">Memory and Capability Evolution <a class="header-anchor" href="#memory-and-capability-evolution" aria-label="Permalink to &quot;Memory and Capability Evolution&quot;">​</a></h1><p class="lead">Memory is not chat history, and more memory is not automatically better. It is a constrained cache for judgment that reduces repeated questions. Capability evolution forms reusable methods from real trajectories and evaluation, rather than letting an agent rewrite its permissions and safety boundaries.</p><h2 id="design-goals" tabindex="-1">Design Goals <a class="header-anchor" href="#design-goals" aria-label="Permalink to &quot;Design Goals&quot;">​</a></h2><p>The system should remember context the user provides repeatedly, preferences, project facts, lessons from past tasks, and work methods that have already been verified. When memory is recalled, Hearth should say where it came from, how trustworthy it is, which scope it applies to, whether it expired, and why it was used.</p><p>Memory must be correctable and forgettable. Users can inspect what the system remembers, fix errors, limit how sensitive information may be used, and confirm that deletion reached indexes, caches, device copies, and derived summaries, not just the original page.</p><p>Capability evolution should form candidate methods from successes, failures, human corrections, takeovers, and cost data. A candidate can be a prompt, a fixed procedure, a document-processing pipeline, a connector recipe, or a set of verification steps. It becomes a default capability only after replay, non-effect trial runs, limited real use, and user review.</p><p>Memory and capability cannot become sources of truth. Task state, approvals, artifacts, and receipts come from records. Memory supplies context and methods. A skill can request only authority the original task already holds; it cannot create credentials, background tasks, or a larger authorization scope.</p><h2 id="design-tradeoffs" tabindex="-1">Design Tradeoffs <a class="header-anchor" href="#design-tradeoffs" aria-label="Permalink to &quot;Design Tradeoffs&quot;">​</a></h2><p>Hearth divides memory into five types with separate lifetimes and uses. This reduces repeated context without turning everything into an unexplainable long-term state.</p><table tabindex="0"><thead><tr><th>Memory type</th><th>What it stores</th><th>Lifetime and use</th></tr></thead><tbody><tr><td>Working memory</td><td>The current goal, constraints, temporary observations, and intermediate results</td><td>Cleared when the task ends; serves only current execution</td></tr><tr><td>Episodic memory</td><td>What happened in past tasks, results, failures, and human corrections</td><td>Kept for the medium term, summarized, and used as reference for similar work</td></tr><tr><td>Fact memory</td><td>People, projects, organizations, and stable relationships</td><td>Kept long term with source, validity period, and sensitivity</td></tr><tr><td>User model</td><td>Preferences, communication style, habits, and value boundaries</td><td>Kept long term, highly editable, and used to reduce repeated explanation</td></tr><tr><td>Method memory</td><td>Verified procedures, tool recipes, and verification methods</td><td>Versioned for repeated tasks and capability evolution</td></tr></tbody></table><p>Memory enters a candidate state before being written. The system checks source, sensitivity, duplication, conflict, and user authorization. Web pages, email, documents, and tool output can all contain misleading content, so a single appearance does not make a high-confidence fact. Highly sensitive information is not written automatically by default.</p><p>Retrieval filters by task need, applicable scope, source trust, freshness, sensitivity, and context budget. The system does not stuff all memory into one task or let different accounts and projects contaminate each other. New facts cannot silently overwrite old ones; conflicts preserve sources and ask for confirmation. Low-confidence memory cannot by itself trigger a high-risk action.</p><p>Forgetting must reach caches and derived summaries. Caches need versions, invalidation, and deletion rules; forgotten content cannot be recalled again. Multi-device sync carries versions and deletion markers so an old device cannot resurrect memory that was deleted.</p><p>Method evolution follows a path: collect trajectories, cluster repeated work and failures, write a candidate explanation, audit permissions, replay offline, run without side effects, use in a limited real scope, then decide to promote, reject, or roll back. Promotion must show that real-task success did not fall, no authority was exceeded, no scope expanded, cost or human time improved measurably, and failures remain explainable and recoverable.</p><p>The system may propose new methods but cannot change its authorization rules, approval thresholds, core safety boundaries, or event formats. Every permission change needs explicit user approval, and core changes go through human review. One successful demo, a model claiming it is better, or lower token use without lower human time is not enough to promote a method.</p>',15)])])}const p=t(s,[["render",i]]);export{h as __pageData,p as default};
